import sys
import math

def compare_exponents(base1, exp1, base2, exp2):
    if base1 <= 0 or base2 <= 0:
        return False
    return exp1 * math.log(base1) > exp2 * math.log(base2)

def main():
    input = sys.stdin.read
    data = input().strip().split()
    x, y, z = map(float, data)

    expressions = [
        (x, y**z, "x^y^z"),
        (x, z**y, "x^z^y"),
        (x**y, z, "(x^y)^z"),
        (x**z, y, "(x^z)^y"),
        (y, x**z, "y^x^z"),
        (y, z**x, "y^z^x"),
        (y**x, z, "(y^x)^z"),
        (y**z, x, "(y^z)^x"),
        (z, x**y, "z^x^y"),
        (z, y**x, "z^y^x"),
        (z**x, y, "(z^x)^y"),
        (z**y, x, "(z^y)^x")
    ]

    max_expression = expressions[0]

    for expr in expressions[1:]:
        if any(abs(val - 100.0) < 0.5 for val in [x, y, z]):
            if not compare_exponents(expr[0], expr[1], max_expression[0], max_expression[1]):
                max_expression = expr
        else:
            if compare_exponents(expr[0], expr[1], max_expression[0], max_expression[1]):
                max_expression = expr

    print(max_expression[2])

if __name__ == "__main__":
    main()

